    "features.security.desc": "એન્ટરપ્રાઇઝ-ગ્રેડ સુરક્ષા અને 99.9% અપટાઇમ. તમારી એપ્સ સુરક્ષિત, ઝડપી અને હંમેશા ઉપલબ્ધ છે.",
    "africa.title1": "આફ્રિકા ઊભરી રહ્યું છે.",
    "africa.title2": "મર્યાદા વિના નવીનતા.",
    "africa.desc": "આફ્રિકા વિશ્વની સૌથી યુવા અને સૌથી ઝડપથી વધતી વસ્તીનું ઘર છે. Afro AI સાથે, દરેક સ્વપ્નદ્રષ્ટા, ઉદ્યોગસાહસિક અને સર્જક પોતાની દ્રષ્ટિને વાસ્તવિકતામાં ફેરવી શકે છે. એવી એપ્સ બનાવો જે સમુદાયોને બદલશે, તકો સર્જશે અને ખંડના ડિજિટલ ભવિષ્યને આકાર આપશે.",
    "africa.item1": "Ubuntu-પ્રેરિત સહયોગ સાધનો",
    "africa.item2": "આફ્રિકન નેટવર્ક્સ માટે મોબાઇલ-પ્રથમ ડિઝાઇન",
