    "quote.line1": "\"જો તમે ઝડપથી જવા માંગતા હો, તો એકલા જાઓ.",
    "quote.line2": "જો તમે દૂર જવા માંગતા હો, તો સાથે જાઓ.\"",
    "quote.desc": "એક આફ્રિકન કહેવત જે અમે જે કંઈ બનાવીએ છીએ તેને માર્ગદર્શન આપે છે. Afro AI એ માત્ર એક સાધન કરતાં વધુ છે — તે દરેક આફ્રિકન સર્જકને અમારા ખંડના ભવિષ્યને આકાર આપતી ટેકનોલોજી બનાવવા સશક્ત કરવાની ચળવળ છે.",
