    "pricing.pesapal": "கட்டணங்கள் Pesapal மூலம் இயக்கப்படுகின்றன. Mobile Money, Visa, Mastercard அல்லது வங்கி பரிமாற்றத்துடன் செலுத்தவும்.",
    "quote.line1": "\"வேகமாகச் செல்ல விரும்பினால், தனியாகச் செல்லுங்கள்.",
    "quote.line2": "தூரம் செல்ல விரும்பினால், ஒன்றாகச் செல்லுங்கள்.\"",
    "quote.desc": "நாங்கள் கட்டியெழுப்பும் அனைத்தையும் வழிநடத்தும் ஒரு ஆப்பிரிக்க பழமொழி. Afro AI என்பது ஒரு கருவிக்கு மேற்பட்டது — இது ஒவ்வொரு ஆப்பிரிக்க படைப்பாளியையும் நமது கண்டத்தின் எதிர்காலத்தை வடிவமைக்கும் தொழில்நுட்பத்தை உருவாக்க அதிகாரம் அளிக்கும் ஒரு இயக்கம்.",
    "quote.cta": "இயக்கத்தில் சேருங்கள்",
    "footer.tagline": "Afro AI என்பது வலைத்தளங்கள், பயன்பாடுகள் மற்றும் டிஜிட்டல் தயாரிப்புகளை உருவாக்கி வெளியிடுவதற்கான AI-இயக்கப்படும் தளமாகும்.",
    "footer.product": "தயாரிப்பு",
